package com.hashpony.core

import com.hashpony.core.backend.ChecksumBackend
import com.hashpony.core.backend.MessageDigestBackend
import com.hashpony.core.xxhash.Xxh32Digest
import com.hashpony.core.xxhash.Xxh3Digest
import com.hashpony.core.xxhash.Xxh64Digest
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.util.zip.Adler32
import java.util.zip.CRC32

/**
 * Verifies every backend against authoritative reference vectors generated by
 * the official xxHash binding (xxh*), zlib (crc32/adler32) and hashlib (SHA-2/3).
 * Each vector is streamed in several chunkings so the internal stripe (64 B) and
 * block (1024 B) boundaries of XXH3 are exercised.
 */
class XxHashVectorTest {

    private fun mdName(algo: String) = when (algo) {
        "md5" -> "MD5"; "sha1" -> "SHA-1"; "sha224" -> "SHA-224"; "sha256" -> "SHA-256"
        "sha384" -> "SHA-384"; "sha512" -> "SHA-512"; "sha3_256" -> "SHA3-256"
        else -> error("unexpected algorithm $algo")
    }

    private fun newDigest(algo: String, seed: String): StreamingDigest = when (algo) {
        "xxh32" -> Xxh32Digest(seed.toUInt())
        "xxh64" -> Xxh64Digest(seed.toULong())
        "xxh3_64" -> Xxh3Digest(64, seed.toULong())
        "xxh3_128" -> Xxh3Digest(128, seed.toULong())
        "crc32" -> ChecksumBackend(CRC32())
        "adler32" -> ChecksumBackend(Adler32())
        else -> MessageDigestBackend.of(mdName(algo))
    }

    private fun hashHex(algo: String, seed: String, data: ByteArray, chunk: Int): String {
        val d = newDigest(algo, seed)
        if (chunk <= 0) {
            d.update(data, 0, data.size)
        } else {
            var off = 0
            while (off < data.size) {
                val n = minOf(chunk, data.size - off)
                d.update(data, off, n)
                off += n
            }
        }
        return Hex.encode(d.digest())
    }

    @Test
    fun referenceVectorsMatchAcrossChunkings() {
        val stream = requireNotNull(javaClass.getResourceAsStream("/xxhash_vectors.tsv")) {
            "missing test resource xxhash_vectors.tsv"
        }
        var checked = 0
        stream.bufferedReader().useLines { lines ->
            for (line in lines) {
                if (line.isBlank()) continue
                val p = line.split("|")
                val algo = p[0]; val seed = p[1]; val data = Hex.decode(p[2]); val expected = p[3]
                for (chunk in intArrayOf(0, 1, 7, 64, 65, 256, 1024)) {
                    assertEquals(
                        "$algo seed=$seed len=${data.size} chunk=$chunk",
                        expected, hashHex(algo, seed, data, chunk),
                    )
                    checked++
                }
            }
        }
        assertTrue("expected a substantial vector set, ran $checked", checked > 5_000)
    }
}
